import{_ as I,o as a,c as e,ag as t}from"./chunks/framework.BFM5MFIQ.js";const l="data:image/svg+xml;base64,",Z=JSON.parse('{"title":"Постоянное хранилище","description":"Что означает постоянное хранилище и что делать, если браузер его не предоставил.","frontmatter":{"title":"Постоянное хранилище","description":"Что означает постоянное хранилище и что делать, если браузер его не предоставил.","order":10},"headers":[],"relativePath":"ru/troubleshooting/persistent-storage.md","filePath":"ru/troubleshooting/persistent-storage.md"}'),r={name:"ru/troubleshooting/persistent-storage.md"};function g(o,i,d,s,C,n){return a(),e("div",null,[...i[0]||(i[0]=[t('<h1 id="постоянное-хранилище" tabindex="-1">Постоянное хранилище <a class="header-anchor" href="#постоянное-хранилище" aria-label="Permalink to &quot;Постоянное хранилище&quot;">​</a></h1><p>Owlbear&#39;s DMH хранит данные кампании локально в браузере. Постоянное хранилище — это рекомендация браузеру не удалять данные автоматически при нехватке места.</p><p>Решение принимает браузер. Он может отказать сайту, который не установлен, редко используется или открыт в приватном окне.</p><p><img src="'+l+'" alt="Настройки сайта в браузере"></p><h2 id="chrome-и-edge" tabindex="-1">Chrome и Edge <a class="header-anchor" href="#chrome-и-edge" aria-label="Permalink to &quot;Chrome и Edge&quot;">​</a></h2><ol><li>Сначала <a href="./../getting-started/install.html">установите приложение</a>. Установленным приложениям браузер чаще предоставляет постоянное хранилище.</li><li>Откройте панель сведений о сайте по значку слева от адресной строки и проверьте <strong>Настройки сайта</strong>.</li><li>Убедитесь, что cookies и данные сайта разрешены.</li><li>Вернитесь в <strong>Настройки → Данные → Постоянное хранилище</strong> и запросите его снова.</li></ol><p>В Chrome и Edge нет отдельного переключателя «постоянное хранилище». Браузер предоставляет его автоматически с учётом установки и активности, поэтому установка приложения и обычное использование — надёжный путь.</p><h2 id="firefox" tabindex="-1">Firefox <a class="header-anchor" href="#firefox" aria-label="Permalink to &quot;Firefox&quot;">​</a></h2><p>Firefox может показать запрос, когда сайт просит постоянное хранилище. Если разрешение было заблокировано, откройте сведения о сайте, проверьте разрешения и попробуйте снова. Также можно проверить настройки сохранённых данных сайтов в браузере.</p><h2 id="safari" tabindex="-1">Safari <a class="header-anchor" href="#safari" aria-label="Permalink to &quot;Safari&quot;">​</a></h2><p>Safari управляет хранилищем отдельно для каждого сайта. Проверьте настройки хранилища сайта в адресной строке или в настройках Safari. На iOS откройте <strong>Настройки → Safari → Дополнения → Данные сайтов</strong>.</p><h2 id="если-браузер-все-равно-отказывает" tabindex="-1">Если браузер всё равно отказывает <a class="header-anchor" href="#если-браузер-все-равно-отказывает" aria-label="Permalink to &quot;Если браузер всё равно отказывает&quot;">​</a></h2><ul><li>Установите приложение и открывайте его из установленной записи.</li><li>Пользуйтесь приложением некоторое время, затем запросите постоянное хранилище снова.</li><li>Перед очисткой данных браузера или изменением настроек сайта сохраните актуальную резервную копию.</li></ul><p><a href="./../getting-started/install.html">Вернуться к установке приложения</a></p>',14)])])}const c=I(r,[["render",g]]);export{Z as __pageData,c as default};
